package org.tinygears.uom.codegen;

/** The headers of the generated files. */
final class Headers {
    /**
     * {@code config/license-header.txt} with a fixed year, so that the output does not depend on the date; Spotless
     * writes the same header into the hand-written files.
     */
    static final String LICENSE = """
            /*
             * Copyright (c) 2026 TinyGears.org
             *
             * This program and the accompanying materials are made available under the
             * terms of the Apache License, Version 2.0 which is available at
             * https://www.apache.org/licenses/LICENSE-2.0.
             *
             * SPDX-License-Identifier: Apache-2.0
             */

            """;

    /** The line after the license header that marks a generated Java file. */
    static final String GENERATED = "// Generated by uom-codegen";

    private Headers() {
    }

    /** The license header and the generated line naming {@code sources}. */
    static String java(String sources) {
        return LICENSE + GENERATED + " from " + sources + "; do not edit.\n";
    }
}
